package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.graphics.Color;import android.widget.*;import org.json.*;
public final class SkinColourEditor {
 public static void form(Activity a,JSONObject player,JSONObject data){
 LinearLayout col=new LinearLayout(a);col.setOrientation(1);int pad=(int)(16*a.getResources().getDisplayMetrics().density);col.setPadding(pad,pad,pad,pad);ScrollView scroll=new ScrollView(a);scroll.addView(col);TextView note=new TextView(a);note.setText("Choose an original game body palette. Preview colours come from game textures; match lighting varies. Reopen the app after saving.");col.addView(note);
 Spinner choice=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,new String[]{"Original","Palette 1","Palette 2","Palette 3","Palette 4","Palette 5","Palette 6"});adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);choice.setAdapter(adapter);choice.setSelection(data.optInt("skin",0));col.addView(choice);JSONArray previews=data.optJSONArray("skin_previews");
 if(previews!=null)for(int i=0;i<previews.length();i++){JSONObject row=previews.optJSONObject(i);int id=row.optInt("id");Button b=new Button(a);b.setText("Palette "+id);b.setAllCaps(false);b.setBackgroundColor(0xff000000|Integer.parseInt(row.optString("hex"),16));b.setTextColor(id<5?Color.BLACK:Color.WHITE);b.setOnClickListener(v->choice.setSelection(id));col.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 AlertDialog d=new AlertDialog.Builder(a).setTitle("Skin · Game palettes").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{JSONObject values=new JSONObject().put("59",data.optInt("59")).put("60",data.optInt("60"));if(choice.getSelectedItemPosition()>0)values.put("skin",choice.getSelectedItemPosition());JSONObject req=new JSONObject(player.toString()).put("values",values);d.getButton(-1).setEnabled(false);new Thread(()->{try{String reply=(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,"ui78_appearance_apply",req.toString());if(!new JSONObject(reply).optBoolean("saved"))throw new Exception("Save not confirmed");a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,"Saved. Reopen the app.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{d.getButton(-1).setEnabled(true);new AlertDialog.Builder(a).setMessage(String.valueOf(e.getCause()==null?e:e.getCause())).setPositiveButton("Close",null).show();});}},"SaveGameSkin").start();}catch(Exception e){Toast.makeText(a,String.valueOf(e),Toast.LENGTH_LONG).show();}});
 }
}
